public Niedax.PIMCore.Models.Product fillDataFromD365(InventTable _inventTable, LanguageId _languageId)
{ 
    KCS_GoodsGroup goodsGroup;
    KCS_ItemUsageIDs kCS_ItemUsageIDs;
    UnitOfMeasure nDX_DeliveryUnit;
    EcoResProduct lEcoResProduct;
    EcoResProductTranslation lEcoResProductTranslation;

    Niedax.PIMCore.Models.Product product = next fillDataFromD365(_inventTable, _languageId);

    lEcoResProduct = EcoResProduct::find(_inventTable.Product);
    lEcoResProductTranslation = EcoResProductTranslation::findByProductLanguage(_inventTable.Product, _languageId);

    goodsGroup = KCS_GoodsGroup::find(_inventTable.KCS_GoodsId);
    kCS_ItemUsageIDs = KCS_ItemUsageIDs::find(_inventTable.KCS_ItemUsageId);

    product.artikelschluessel = _inventTable.KCS_ItemUsageId;
    product.artikelschluesseltext = KCS_ItemUsageIds::find(_inventTable.KCS_ItemUsageId).KCS_ItemUsageDescription;

    product.artikelbeschreibung = lEcoResProductTranslation.NDXProductName1 + " " + lEcoResProductTranslation.NDXProductName2;

    product.artikellangbezeichnung = '';
    product.ausschreibungstext  = '';

    return product;
}
